// ===================================================================
const cfg = {
  her: {
    name:  'Her name',
    phone: '+61400000000',          // only used by the courier, for the drop-off
    telegram_chat: '123456789',     // she messages your bot once; her chat id goes here
    work:  { name: 'her work (the café on Oxford St, Leederville)', lat: -31.9365, lon: 115.8418 },  // swap for hers
    home_address: '1 Example St, Leederville WA 6007',   // where dinner gets dropped
  },
  me:              { name: 'Your name', phone: '+61400000001', telegram_chat: '987654321' },
  shortcut_secret: 'CHANGE-ME',         // the iPhone Shortcut sends this with every ping
  flowers: {
    order:            '12 pink roses',
    card:             'Thinking of you. x',
    deliver_by:       '4:30pm',
    search_radius_m:  3000,
    fallback_email:   'orders@your-florist.com.au',  // used if the closest shop lists no email
    fallback_florist: { name: 'Your usual florist', email: 'orders@your-florist.com.au', website: '' },
    order_inbox:      '',                            // set to your own email to test safely
  },
  boys_night:    { match: 'boys', move_days: 7 },
  comfort_order: { store: "Grill'd", favourite: 'Mustard & Pickled!', sides: 'Sweet Potato Chips' },
  uber_direct: {
    customer_id: 'YOUR_UBER_DIRECT_CUSTOMER_ID',
    pickup: { name: "Grill'd (your closest)", phone: '+61800000000',
              address: 'Your closest Grill\'d street address, suburb WA postcode' },
  },
  netflix_history_csv: 'https://docs.google.com/spreadsheets/d/YOUR_SHEET_ID/export?format=csv',
};

// The box "Find the closest florist" searches: her work, +/- search_radius_m.
const w = cfg.her.work, r = cfg.flowers.search_radius_m;
const dLat = r / 111320, dLon = r / (111320 * Math.cos(w.lat * Math.PI / 180));
cfg.search_box = [w.lon - dLon, w.lat + dLat, w.lon + dLon, w.lat - dLat].map(n => n.toFixed(5)).join(',');
return [{ json: cfg }];

// ===================================================================
//  Where is she in her cycle?
//  Luteal phase = the ~14 days between ovulation and her next period.
//  So luteal day 1 is (next period - 14 days), which for a 28-day
//  cycle is cycle day 15.
// ===================================================================
const c = $('Her cycle (iPhone Shortcut)').first().json.body;
const DAY = 86400000;
const iso = d => new Date(d).toISOString().slice(0, 10);

const today = Date.parse(new Date().toLocaleDateString('en-CA', { timeZone: 'Australia/Perth' }));
const start = Date.parse(c.last_period_start);
const len = Number(c.avg_cycle_days) || 28;
if (!isFinite(start)) throw new Error('No period start came through from her Shortcut');

const cycleDay = (Math.floor((today - start) / DAY) % len) + 1;
const lutealFrom = len - 13;                 // day 15 of a 28-day cycle
const nextPeriod = start + Math.ceil((today - start + 1) / (len * DAY)) * len * DAY;

return [{ json: {
  cycle_day:      cycleDay,
  phase:          cycleDay <= 5 ? 'period' : cycleDay < lutealFrom ? 'follicular' : 'luteal',
  luteal_day_1:   iso(nextPeriod - 14 * DAY),
  next_period:    iso(nextPeriod),
  days_to_period: Math.round((nextPeriod - today) / DAY),
  luteal_today:   cycleDay === lutealFrom,
} }];

// ===================================================================
//  Remember her cycle. n8n's workflow static data is Linda's memory:
//  it survives between runs of an ACTIVE workflow, no database needed.
// ===================================================================
const cfg = $('⚙️ Settings · cycle').first().json;
const hook = $('Her cycle (iPhone Shortcut)').first().json;
const sent = (hook.body && hook.body.secret) || (hook.headers && hook.headers['x-linda-secret']);
if (sent !== cfg.shortcut_secret) throw new Error('Wrong Shortcut secret, ignoring this ping');

const s = $getWorkflowStaticData('global');
const c = $input.first().json;
s.luteal_day_1 = c.luteal_day_1;
s.next_period  = c.next_period;
s.updated_at   = new Date().toISOString();
return [{ json: Object.assign({ saved: true }, c) }];

