//  doesn't, the next node reads it off the florist's own website.
// ===================================================================
const cfg = $('⚙️ Settings · reply').first().json;
const w = cfg.her.work;
const rad = Math.PI / 180;
const km = (a, b) => {
  const x = Math.sin((b.lat - a.lat) * rad / 2) ** 2 +
            Math.cos(a.lat * rad) * Math.cos(b.lat * rad) * Math.sin((b.lon - a.lon) * rad / 2) ** 2;
  return 6371 * 2 * Math.asin(Math.sqrt(x));
};

// n8n hands a JSON array over as one item per result
const shops = $input.all().map(i => i.json).filter(e => e && e.lat).map(e => {
