const page = String($input.first().json.data || '');
const found = (page.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i) || [])[0] || '';
const floristEmail = f.email || (/\.(png|jpe?g|gif|webp)$/i.test(found) ? '' : found) || cfg.flowers.fallback_email;

const html =
  '<p>Hi ' + f.name + ' team,</p>' +
  '<p>Could I please order <b>' + cfg.flowers.order + '</b> for delivery <b>today, before ' +
  cfg.flowers.deliver_by + '</b>, to ' + cfg.her.name + ' at ' + cfg.her.work.name + '.</p>' +
  '<p>Card message: <i>"' + cfg.flowers.card + '"</i></p>' +
