parameters.jsonBody:
={{ JSON.stringify({
  code: `export default async function ({ page, context }) {
    // Grill'd has no ordering API. This drives grilld.com.au like you would.
    // Selectors are text-based so they survive restyles; check them once.
    await page.goto('https://grilld.com.au/', { waitUntil: 'networkidle2' });
    await page.locator('::-p-text(Order Now)').click();
    await page.locator('::-p-text(Log in)').click();
    await page.locator('input[type=email]').fill(context.email);
    await page.locator('input[type=password]').fill(context.password);
    await page.keyboard.press('Enter');
    await page.waitForNavigation({ waitUntil: 'networkidle2' });
    await page.locator('::-p-text(Pick up)').click();
    await page.locator('::-p-text(Favourites)').click();
    await page.locator('::-p-text(' + context.favourite + ')').click();
    await page.locator('::-p-text(Reorder)').click();
    await page.locator('::-p-text(Checkout)').click();
    await page.locator('::-p-text(Place order)').click();
    await page.waitForSelector('text/Order number');
    const order = await page.$eval('body', b => (b.innerText.match(/Order number[:\\s]*([A-Z0-9-]+)/) || [])[1]);
    return { data: { order }, type: 'application/json' };
  }`,
  context: { email: 'YOUR_GRILLD_EMAIL', password: 'YOUR_GRILLD_PASSWORD',
             favourite: $('⚙️ Settings · dinner').first().json.comfort_order.favourite }
}) }}

