    fallback_florist: { name: 'Your usual florist', email: 'orders@your-florist.com.au', website: '' },
    order_inbox:      '',                            // set to your own email to test safely
  },
  boys_night:    { match: 'boys', move_days: 7 },
  comfort_order: { store: "Grill'd", favourite: 'Mustard & Pickled!', sides: 'Sweet Potato Chips' },
  uber_direct: {
    customer_id: 'YOUR_UBER_DIRECT_CUSTOMER_ID',
    pickup: { name: "Grill'd (your closest)", phone: '+61800000000',
              address: 'Your closest Grill\'d street address, suburb WA postcode' },
  },
  netflix_history_csv: 'https://docs.google.com/spreadsheets/d/YOUR_SHEET_ID/export?format=csv',
};

// The box "Find the closest florist" searches: her work, +/- search_radius_m.
const w = cfg.her.work, r = cfg.flowers.search_radius_m;
const dLat = r / 111320, dLon = r / (111320 * Math.cos(w.lat * Math.PI / 180));
cfg.search_box = [w.lon - dLon, w.lat + dLat, w.lon + dLon, w.lat - dLat].map(n => n.toFixed(5)).join(',');
return [{ json: cfg }];

// Uber Direct posts every status change. "On the way" = pickup_complete or
// dropoff (the driver has the food and is heading to her). Whichever lands first fires.
const b = $('Uber Direct: status update').first().json.body || {};
const s = $getWorkflowStaticData('global');
const id = b.delivery_id || (b.data && b.data.id);
const onTheWay = ['pickup_complete', 'dropoff'].includes(b.status);
const go = b.kind === 'event.delivery_status' && onTheWay
        && id === s.delivery_id && s.movies_for !== id;
if (go) s.movies_for = id;
return [{ json: { go, status: b.status || null } }];

// Her Netflix Viewing Activity CSV: "Title","Date". Pull the titles.
const csv = String($input.first().json.data || '');
const rows = csv.split(/\r?\n/).slice(1).filter(Boolean);
const watched = rows.map(r => (r.match(/^"((?:[^"]|"")*)"/) || [, r.split(',')[0]])[1].replace(/""/g, '"'));
return [{ json: { watched } }];

// ===================================================================
//  Fresh on Netflix vs what she's already watched.
//  Netflix's Viewing Activity CSV writes episodes as
//  "Show: Season 1: Episode", so compare on the part before the colon.
// ===================================================================
const norm = s => String(s || '').toLowerCase().split(':')[0].replace(/[^a-z0-9]/g, '');
const watched = new Set(($('Read her history').first().json.watched || []).map(norm));

const scraped = $('Apify: new on Netflix AU').all().map(i => i.json).filter(m => m.title);
const fresh = scraped.filter(m => !watched.has(norm(m.title)) && !watched.has(norm(m.originalTitle)));

const lines = fresh.map(m => '- ' + m.title + ' · ' + (m.releaseYear || '?') + ' · ' +
  (m.genres || []).join(', ') + ' · IMDb ' + (m.imdbScore || '?') + ' · ' +
  String(m.shortDescription || '').slice(0, 160));

return [{ json: {
  scraped:         scraped.length,
  already_watched: scraped.length - fresh.length,
  candidates:      fresh.length,
  candidates_text: lines.join('\n'),
} }];

